'use client';

import { useEffect, useState } from 'react';
import { JsonRpcProvider, Contract, formatEther } from 'ethers';
import Link from 'next/link';

declare global {
  interface Window {
    ethereum?: any;
  }
}

const NEXTIA_ABI = [
  'function balanceOf(address account) external view returns (uint256)',
];

export default function Home() {
  const [balance, setBalance] = useState('0');
  const [address, setAddress] = useState('');
  const [loading, setLoading] = useState(true);
  const [network, setNetwork] = useState('');
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const connectWallet = async () => {
      try {
        if (!window.ethereum) {
          setError('MetaMask no detectado');
          setLoading(false);
          return;
        }

        const accounts = await window.ethereum.request({
          method: 'eth_requestAccounts',
        });
        const userAddress = accounts[0];
        setAddress(userAddress);
        setConnected(true);

        const provider = new JsonRpcProvider(
          'https://eth-sepolia.g.alchemy.com/v2/demo'
        );
        const tokenAddress = '0x889C1eA94F67588c7bC733Dc368D3059DE9891CE';

        const tokenContract = new Contract(
          tokenAddress,
          NEXTIA_ABI,
          provider
        );

        const bal = await tokenContract.balanceOf(userAddress);
        setBalance(formatEther(bal));
        setNetwork('Sepolia');
        setError('');
      } catch (err) {
        console.error('Error:', err);
        setError('Error al conectar wallet');
      } finally {
        setLoading(false);
      }
    };
    connectWallet();
  }, []);

  return (
    <div style={{ minHeight: '100vh', backgroundColor: 'var(--bg-dark)', color: 'var(--text-primary)' }}>
      <nav style={{
        borderBottom: '1px solid var(--border-color)',
        backdropFilter: 'blur(10px)',
        position: 'sticky',
        top: 0,
        zIndex: 50,
        backgroundColor: 'rgba(15, 15, 15, 0.8)'
      }}>
        <div style={{
          maxWidth: '1200px',
          margin: '0 auto',
          padding: '16px 24px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}>
            <div style={{
              width: '32px',
              height: '32px',
              background: 'linear-gradient(135deg, #00D4FF, #5514B4)',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '18px',
              fontWeight: 'bold'
            }}>
              ◆
            </div>
            <span style={{
              fontFamily: "'Montserrat', sans-serif",
              fontSize: '18px',
              fontWeight: '700',
              background: 'linear-gradient(90deg, #00D4FF, #f10050)',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              NextiaToken
            </span>
          </div>

          <div style={{ display: 'flex', gap: '32px' }}>
            <Link href="/" style={{ textDecoration: 'none', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
              Home
            </Link>
            <Link href="/staking" style={{ textDecoration: 'none', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
              Staking
            </Link>
            <Link href="/leaderboard" style={{ textDecoration: 'none', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
              Leaderboard
            </Link>
          </div>
        </div>
      </nav>

      <main style={{
        maxWidth: '800px',
        margin: '0 auto',
        padding: '60px 24px'
      }}>
        <div style={{ textAlign: 'center', marginBottom: '60px' }}>
          <h1 style={{
            fontFamily: "'Montserrat', sans-serif",
            fontSize: '48px',
            fontWeight: '800',
            marginBottom: '12px',
            background: 'linear-gradient(90deg, #00D4FF, #f10050)',
            backgroundClip: 'text',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent'
          }}>
            NextiaToken DApp
          </h1>
          <p style={{
            color: 'var(--text-secondary)',
            fontSize: '16px',
            lineHeight: '1.6'
          }}>
            Staking descentralizado con rewards automáticos
          </p>
        </div>

        {loading ? (
          <div style={{
            background: 'rgba(0, 212, 255, 0.05)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            padding: '48px',
            textAlign: 'center'
          }}>
            <div style={{
              display: 'inline-block',
              animation: 'spin 1s linear infinite',
              fontSize: '32px'
            }}>
              ⚙️
            </div>
            <p style={{ marginTop: '16px', color: 'var(--text-secondary)' }}>
              Conectando wallet...
            </p>
          </div>
        ) : error ? (
          <div style={{
            background: 'rgba(241, 0, 80, 0.1)',
            border: '1px solid rgba(241, 0, 80, 0.3)',
            borderRadius: '16px',
            padding: '24px',
            textAlign: 'center',
            color: '#f10050'
          }}>
            ⚠️ {error}
          </div>
        ) : !connected ? (
          <div style={{
            background: 'rgba(0, 212, 255, 0.05)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            padding: '40px',
            textAlign: 'center'
          }}>
            <p style={{
              fontSize: '16px',
              fontWeight: '600',
              marginBottom: '8px'
            }}>
              Conecta MetaMask
            </p>
            <p style={{ color: 'var(--text-secondary)' }}>
              Necesitas MetaMask en Sepolia testnet
            </p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
            <div style={{
              background: 'var(--bg-card)',
              border: '1px solid var(--border-color)',
              borderRadius: '16px',
              padding: '20px',
            }}>
              <p style={{ fontSize: '12px', color: 'var(--text-muted)', marginBottom: '8px', textTransform: 'uppercase' }}>
                Wallet conectada
              </p>
              <p style={{
                fontFamily: 'monospace',
                fontSize: '13px',
                color: 'var(--color-secondary)',
                wordBreak: 'break-all'
              }}>
                {address}
              </p>
            </div>

            <div style={{
              background: 'rgba(0, 212, 255, 0.05)',
              border: '2px solid var(--color-secondary)',
              borderRadius: '16px',
              padding: '32px',
              textAlign: 'center'
            }}>
              <p style={{
                fontSize: '13px',
                color: 'var(--text-secondary)',
                marginBottom: '12px',
                textTransform: 'uppercase',
                fontWeight: '600'
              }}>
                Tu Balance
              </p>
              <p style={{
                fontFamily: "'Montserrat', sans-serif",
                fontSize: '40px',
                fontWeight: '800',
                color: 'var(--color-secondary)',
                marginBottom: '8px'
              }}>
                {parseFloat(balance).toFixed(2)}
              </p>
              <p style={{ fontSize: '13px', color: 'var(--color-secondary)' }}>
                NXT • {network}
              </p>
            </div>

            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr 1fr',
              gap: '16px'
            }}>
              {[
                { label: 'STAKED', value: '0.00', icon: '📍' },
                { label: 'REWARDS', value: '0.00', icon: '🎁' },
                { label: 'APY', value: '5%', icon: '📈' }
              ].map((stat, i) => (
                <div key={i} style={{
                  background: 'var(--bg-card)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '12px',
                  padding: '16px',
                  textAlign: 'center'
                }}>
                  <p style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '8px', textTransform: 'uppercase' }}>
                    {stat.label}
                  </p>
                  <p style={{ fontSize: '20px', fontWeight: '700', color: 'var(--color-secondary)' }}>
                    {stat.value}
                  </p>
                </div>
              ))}
            </div>

            <div style={{
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '16px',
              marginTop: '16px'
            }}>
              <Link href="/staking" style={{ textDecoration: 'none' }}>
                <button style={{
                  width: '100%',
                  background: 'var(--color-primary)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '50px',
                  padding: '14px 20px',
                  fontWeight: '600',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}>
                  Stakear NXT
                </button>
              </Link>
              <Link href="/leaderboard" style={{ textDecoration: 'none' }}>
                <button style={{
                  width: '100%',
                  background: 'transparent',
                  color: 'var(--color-secondary)',
                  border: '1px solid var(--border-color)',
                  borderRadius: '50px',
                  padding: '14px 20px',
                  fontWeight: '600',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}>
                  Leaderboard
                </button>
              </Link>
            </div>
          </div>
        )}

        <div style={{
          textAlign: 'center',
          marginTop: '80px',
          paddingTop: '40px',
          borderTop: '1px solid var(--border-color)',
          color: 'var(--text-muted)',
          fontSize: '13px'
        }}>
          <p>Powered by NextiaToken • Sepolia Testnet</p>
        </div>
      </main>
    </div>
  );
}
